-- ============================================================================
-- Carga manual de leads CLARO gestionados fuera del sistema (hoja JUN26)
-- Generado automaticamente desde OLD/LEADSCLARO.xlsx  -  105 filas embebidas
-- ============================================================================
-- DECISIONES APLICADAS (revisar antes de produccion):
--   * id_equipo = 2 (ClaroTeam), por la membresia de los asesores que gestionaron.
--   * id_campana = NULL (la col E del sheet esta revuelta; no se mapeo).
--   * REGISTRO  -> ASESOR_GTR Anny Yoselin Prieto Ovalles (empleado_id 17).
--   * TIPIFICACION preventa -> el asesor real que tipifico (empleado_id + rol reales).
--   * PAOLA y ALBRU -> id_actor NULL, solo nombre (no se atribuyen como SALES).
--   * VENTA (2do evento): VC DESAPROBADA y EDIFICIO SIN LIBERAR -> DESAPROBADO/DESAPROBADO.
--   * Telefonos que YA existen como lead se SALTAN en runtime (no duplica).
--   * nombre_actor/rol_actor se resuelven desde eventos existentes (calce con data real).
-- Idempotente: re-ejecutar no duplica (salta si el lead ya existe).
-- Ejecutar dentro de una transaccion; revisar el NOTICE final antes de COMMIT real.
-- ============================================================================

BEGIN;

CREATE TEMP TABLE seed_lc (
  fila int, telefono text, etapa text, estado text, base text,
  dni text, direccion text,
  prev_tip text, prev_sub text, primera_tip text, primera_sub text,
  prev_actor_id bigint, prev_actor_nombre text, prev_actor_rol text, id_asesor_preventa bigint,
  lead_tip_etapa text, lead_tip text, lead_sub text, lead_asignado_nombre text,
  tiene_venta boolean, venta_tip text, venta_sub text, venta_comentario text, venta_asignado_nombre text,
  ts_registro timestamptz, ts_prev_tip timestamptz, fecha_preventa timestamptz,
  ts_asig_venta timestamptz, ts_venta_tip timestamptz, last_entry_at timestamptz
) ON COMMIT DROP;


-- nombre_actor / rol_actor canonicos desde eventos ya existentes (byte-match)
CREATE TEMP TABLE actor_ref ON COMMIT DROP AS
SELECT DISTINCT ON (id_actor) id_actor, nombre_actor, rol_actor
FROM evento
WHERE id_actor IN (5,17,35,900001,900002,900003,900041,900042,900043,900044,900045)
  AND nombre_actor IS NOT NULL
ORDER BY id_actor, created_at DESC;

DO $$
DECLARE
  rec RECORD;
  v_contacto bigint; v_lead bigint;
  v_ltip bigint; v_lsub bigint; v_vtip bigint; v_vsub bigint;
  v_an text; v_ar text;
  v_ins int := 0; v_skip int := 0;
  c_equipo CONSTANT bigint := 2;
BEGIN
  FOR rec IN SELECT * FROM seed_lc ORDER BY fila LOOP
    IF EXISTS (SELECT 1 FROM lead WHERE prefijo = '+51' AND lead = rec.telefono) THEN
      v_skip := v_skip + 1;
      CONTINUE;
    END IF;

    VALUES ('+51', rec.telefono, NULL, rec.ts_registro, rec.last_entry_at)
    ON CONFLICT (prefijo, lead) DO UPDATE SET updated_at = EXCLUDED.updated_at
    RETURNING id INTO v_contacto;

    v_ltip := NULL; v_lsub := NULL;
    IF rec.lead_tip_etapa IS NOT NULL THEN
      SELECT t.id, st.id INTO v_ltip, v_lsub
      FROM tipificacion t JOIN subtipificacion st ON st.tipificacion_id = t.id
      WHERE t.etapa = rec.lead_tip_etapa AND t.codigo = rec.lead_tip AND st.codigo = rec.lead_sub;
    END IF;

      prefijo, lead, id_contacto, id_equipo, etapa, estado,
      id_asesor_asignado, nombre_asesor_asignado, id_campana, base,
      id_tipificacion, codigo_tipificacion, id_subtipificacion, codigo_subtipificacion,
      primera_codigo_tipificacion, primera_codigo_subtipificacion,
      numero_documento_titular_servicio_snapshot, direccion_snapshot,
      id_asesor_preventa, fecha_preventa,
      created_at, last_entry_at, updated_at
    ) VALUES (
      '+51', rec.telefono, v_contacto, c_equipo, rec.etapa, rec.estado,
      NULL, rec.lead_asignado_nombre, NULL, rec.base,
      v_ltip, rec.lead_tip, v_lsub, rec.lead_sub,
      rec.primera_tip, rec.primera_sub,
      rec.dni, rec.direccion,
      rec.id_asesor_preventa, rec.fecha_preventa,
      rec.ts_registro, rec.last_entry_at, rec.last_entry_at
    ) RETURNING id INTO v_lead;

    -- REGISTRO (GTR Anny, emp 17)
    SELECT nombre_actor, rol_actor INTO v_an, v_ar FROM actor_ref WHERE id_actor = 17;
    VALUES (v_lead, NULL, 17, COALESCE(v_an, 'Anny Yoselin Prieto Ovalles'),
            COALESCE(v_ar, 'ASESOR_GTR'), 'REGISTRO', 'PREVENTA', rec.ts_registro);

    -- TIPIFICACION preventa (asesor real; Paola/ALBRU van con id NULL + nombre)
    v_an := NULL; v_ar := NULL;
    IF rec.prev_actor_id IS NOT NULL THEN
      SELECT nombre_actor, rol_actor INTO v_an, v_ar FROM actor_ref WHERE id_actor = rec.prev_actor_id;
    END IF;
                        tipificacion, subtipificacion, created_at)
    VALUES (v_lead, NULL, rec.prev_actor_id,
            COALESCE(v_an, rec.prev_actor_nombre), COALESCE(v_ar, rec.prev_actor_rol),
            'TIPIFICACION', 'PREVENTA', rec.prev_tip, rec.prev_sub, rec.ts_prev_tip);

    -- 2do evento: ASIGNACION + TIPIFICACION en VENTA (BackOffice ALBRU)
    IF rec.tiene_venta THEN
                          id_asesor_asignado, nombre_asesor_asignado, created_at)
      VALUES (v_lead, NULL, NULL, 'ALBRU', 'ASESOR_BACKOFFICE', 'ASIGNACION', 'VENTA',
              NULL, rec.venta_asignado_nombre, rec.ts_asig_venta);

                          tipificacion, subtipificacion, comentario, created_at)
      VALUES (v_lead, NULL, NULL, 'ALBRU', 'ASESOR_BACKOFFICE', 'TIPIFICACION', 'VENTA',
              rec.venta_tip, rec.venta_sub, rec.venta_comentario, rec.ts_venta_tip);
    END IF;

    v_ins := v_ins + 1;
  END LOOP;
  RAISE NOTICE 'Leads insertados: %, saltados (telefono ya existia): %', v_ins, v_skip;
END $$;

-- Revisa el NOTICE de arriba. Si todo OK:   COMMIT;   si algo falla:   ROLLBACK;
COMMIT;
